/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_payment_after_insert` AFTER INSERT ON `payment_splits` FOR EACH ROW BEGIN
    UPDATE customer_sales
    SET
        received_amount = (
            SELECT COALESCE(SUM(amount_paid), 0)
            FROM payment_splits
            WHERE sale_id = NEW.sale_id
        ),
        status = CASE
            WHEN (
                SELECT COALESCE(SUM(amount_paid), 0)
                FROM payment_splits
                WHERE sale_id = NEW.sale_id
            ) >= gross_sales
            THEN 'Close'
            ELSE 'Open'
        END
    WHERE sale_id = NEW.sale_id;
END */;;
DELIMITER ;
